// Example of how maxResponseSize might be enforced in Ky

const ky = async (url, options = {}) => {
  const { maxResponseSize = Infinity } = options;

  const response = await fetch(url, options);
  const { body, headers } = response;

  if (!body) {
    throw new Error('Response body is missing');
  }

  let totalSize = 0;
  const controlledStream = new ReadableStream({
    async start(controller) {
      const reader = body.getReader();
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunkSize = value.length;
        if (totalSize + chunkSize > maxResponseSize) {
          controller.error(new Error('Response size exceeds maxResponseSize'));
          reader.releaseLock();
          return;
        }

        controller.enqueue(value);
        totalSize += chunkSize;
      }
      controller.close();
    }
  });

  return new Response(controlledStream, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers
  });
};

// Usage
